#include <Servo.h>

Servo meuServo;

void setup() {
  meuServo.attach(9); // fio de sinal no pino 9
}

void loop() {
  // vai de 0° até 180°
  for (int angulo = 0; angulo <= 180; angulo += 2) {
    meuServo.write(angulo);
    delay(15);
  }
  // volta de 180° até 0°
  for (int angulo = 180; angulo >= 0; angulo -= 2) {
    meuServo.write(angulo);
    delay(15);
  }
}

