#include <Servo.h>

Servo meuServo;

void setup() {
  meuServo.attach(9);
  Serial.begin(9600);
}

void loop() {
  meuServo.write(0);
  Serial.println("0 graus");
  delay(1000);
  meuServo.write(90);
  Serial.println("90 graus");
  delay(1000);
  meuServo.write(180);
  Serial.println("180 graus");
  delay(1000);
}
